import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.BM5YPQmL.js";const f=JSON.parse('{"title":"Open Cube OS 文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),l={name:"zh/index.md"};function o(i,e,h,n,s,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="open-cube-os-文档" tabindex="-1">Open Cube OS 文档 <a class="header-anchor" href="#open-cube-os-文档" aria-label="Permalink to &quot;Open Cube OS 文档&quot;">​</a></h1><p>欢迎使用 Open Cube OS 文档中心 - 这是一套从头编写、直接启动进 Ring 3 的 x86_64 内核（L0 是纯服务内核；整个用户世界 —— ush Shell、TUI 桌面、中文控制台 —— 都在 <code>src/L1/</code> 下的 L1 里）。</p><p>所有内容均基于真实代码库编写：命令计数、接口表和行统计均为机器生成（<code>make api-docs</code> -&gt; <code>docs/data/*.json</code>），且手册页引用了实现其描述内容的文件。</p><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><ul><li>系统新手：<a href="./manual/getting-started.html">快速上手</a></li><li>想要构建：<a href="./dev/environment.html">开发环境</a> 然后 <a href="./root/BUILDING.html">BUILDING.md</a></li><li>想要扩展：<a href="./l1/overview.html">L1 扩展指南</a></li><li>架构问题：<a href="./root/ARCHITECTURE.html">Open Cube OS 架构</a> 然后 查看 <a href="./arch/">arch/</a> 下的深度解析</li><li>遇到问题：<a href="./troubleshooting/common-errors.html">故障排查</a></li></ul><h2 id="文档库" tabindex="-1">文档库 <a class="header-anchor" href="#文档库" aria-label="Permalink to &quot;文档库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="./manual/">manual/</a></td><td>用户手册：启动、Shell、文件、网络、TUI、OTA、恢复 + 全部 233 条命令页面</td></tr><tr><td><a href="./dev/">dev/</a></td><td>开发者手册：环境、构建、QEMU、调试、测试、PR 规范、可移植性、风格</td></tr><tr><td><a href="./arch/">arch/</a></td><td>架构深度解析：启动流程、内存、调度器、中断、Ring 3、VFS、网络、驱动、TUI</td></tr><tr><td><a href="./l1/">l1/</a></td><td>L1 扩展指南：接口面、驱动家族、编写模块、共享对象加载器</td></tr><tr><td><a href="./drivers/">drivers/</a></td><td>驱动点亮手册：16 个家族</td></tr><tr><td><a href="./troubleshooting/">troubleshooting/</a></td><td>错误目录和 QEMU 调试</td></tr><tr><td><a href="./internals/">internals/</a></td><td>子系统内部机制：看门狗、klog、健康监控、崩溃转储、加密核心、OTA/A-B</td></tr><tr><td><a href="./release/">release/</a></td><td>发布工程：流程 SOP、版本号、官网 + Wiki 同步</td></tr></tbody></table><h2 id="快速数据-3-0-0-wp06g3" tabindex="-1">快速数据（3.0.0-WP06g3） <a class="header-anchor" href="#快速数据-3-0-0-wp06g3" aria-label="Permalink to &quot;快速数据（3.0.0-WP06g3）&quot;">​</a></h2><ul><li>285 条 Shell 命令 —— 274 个 Ring 3 注册表应用 + 11 个 ush 内建，L0 里零条命令（在访客系统中运行 <code>help -a</code>）</li><li>20 个 SYS_L1SVC 服务类别 / 190 个编号条目（INTERFACES.md，l1svc_defs.h）</li><li>54 个系统调用（<code>src/L0/services/sysapi/core_syscall.h</code>）</li><li>128,890 行原创源代码，624 个文件</li><li>Apache 2.0 许可，每个文件均带有 SPDX 标签</li></ul>',9)])])}const m=t(l,[["render",o]]);export{f as __pageData,m as default};
